async function readTitle(url, signal) {
  const response = await fetch(url, { signal });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const data = await response.json();
  if (typeof data.title !== "string") throw new TypeError("Invalid response shape");
  return data.title;
}
console.log("Check response.ok before parsing trusted application data.");

class ValidationError extends Error {
  constructor(message, options) { super(message, options); this.name = "ValidationError"; }
}
function parseAge(value) {
  if (!Number.isInteger(value) || value < 0) throw new ValidationError("Age must be a non-negative integer");
  return value;
}
